    {
      "id": 4,
      "claim": "The current drawn by one parallel branch does not change the voltage across the other branches (the supply maintains voltage).",
      "evidence": "Kirchhoff’s current law and the fact that household power sources are designed to keep voltage constant under normal load variations.",
      "weight": 0.15,
      "depends_on": [3]
    },
